-- Permanent rewards use canonical Shikimori IDs, as history.anime_id does.
-- Existing Plus pins and all earned cosmetics keep their access rules.
SELECT ua.user_id,ar.cosmetic_id,ua.unlocked_at,'achievement',ua.achievement_id || ':' || c.slug,jsonb_build_object('achievement',a.slug)
FROM user_achievements ua JOIN achievement_rewards ar ON ar.achievement_id=ua.achievement_id
JOIN cosmetics c ON c.id=ar.cosmetic_id JOIN achievements a ON a.id=ua.achievement_id
WHERE c.slug='achievement-one-piece' ON CONFLICT DO NOTHING;
SELECT r.referrer_id,'frame:' || reward.slug,(extract(epoch FROM clock_timestamp())*1000)::bigint,
'referral','referral:' || reward.threshold || ':' || reward.slug,jsonb_build_object('milestone',reward.threshold)
FROM referrals r CROSS JOIN (VALUES ('referral-bloom',1),('referral-wings',3),('referral-tide',5),('referral-phoenix',25)) reward(slug,threshold)
WHERE r.status='qualified' GROUP BY r.referrer_id,reward.slug,reward.threshold
HAVING count(*)>=reward.threshold ON CONFLICT DO NOTHING;
